var a=256;var i=[{id:`cooking-256-01`,theoryId:256,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which distinction best describes a hydrocolloid thickener versus a gel?`,ua:`Яка відмінність найкраще описує загусник-гідроколоїд і гель?`},explanation:{en:`Viscosity and gel structure describe different rheological behaviors.`,ua:`В’язкість і гелева структура характеризують різні реологічні властивості.`},options:[{id:`a`,text:{en:`Every thickened liquid must become a solid gel`,ua:`Будь-яка загущена рідина обов’язково стає твердим гелем`}},{id:`b`,text:{en:`Hydrocolloids always replace heating with no other constraints`,ua:`Гідроколоїди завжди замінюють нагрівання без інших умов`}},{id:`c`,text:{en:`A thickened liquid can still flow, while a gel has a network that resists deformation`,ua:`Загущена рідина може текти, тоді як гель має сітку, що чинить опір деформації`}}],answer:{optionIds:[`c`]}},{id:`cooking-256-02`,theoryId:256,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Agar and xanthan gum can always replace each other gram for gram.`,ua:`Агар і ксантанова камедь завжди взаємозамінні грам на грам.`},explanation:{en:`They hydrate, thicken or gel under different conditions and yield different structures.`,ua:`Вони гідратуються, загущують або утворюють гелі за різних умов і дають різні структури.`},answer:{value:!1}},{id:`cooking-256-03`,theoryId:256,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match modernist hydrocolloids with typical behavior.`,ua:`Поєднайте модерністські гідроколоїди з типовою поведінкою.`},explanation:{en:`Use food-grade ingredients and formulation-specific procedures.`,ua:`Використовуйте харчові інгредієнти й технологію, відповідну рецептурі.`},leftItems:[{id:`l1`,text:{en:`Agar`,ua:`Агар`}},{id:`l2`,text:{en:`Xanthan gum`,ua:`Ксантанова камедь`}},{id:`l3`,text:{en:`Alginate`,ua:`Альгінат`}}],rightItems:[{id:`r2`,text:{en:`Thickens and stabilizes many liquids`,ua:`Загущує та стабілізує багато рідин`}},{id:`r3`,text:{en:`Can form calcium-linked gels`,ua:`Може утворювати гелі з кальцієвими зв’язками`}},{id:`r1`,text:{en:`Forms a heat-set gel after cooling`,ua:`Утворює гель після нагрівання й охолодження`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-256-04`,theoryId:256,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A smoothie needs slight body but not a sliceable gel. What is a sensible first strategy?`,ua:`Смузі потрібно трохи густини, але не щільний гель для нарізання. Яка стратегія доречна?`},explanation:{en:`Start with a documented low-dose trial, measuring and observing texture.`,ua:`Почніть із документованої проби малої концентрації, вимірюючи та оцінюючи текстуру.`},options:[{id:`a`,text:{en:`Add an uncontrolled large amount of agar`,ua:`Додати велику неконтрольовану кількість агару`}},{id:`b`,text:{en:`Assume all powders are identical`,ua:`Вважати всі порошки однаковими`}},{id:`c`,text:{en:`Test a small controlled amount of an appropriate thickener`,ua:`Випробувати невелику контрольовану кількість відповідного загусника`}}],answer:{optionIds:[`c`]}},{id:`cooking-256-05`,theoryId:256,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which factors can change hydrocolloid performance?`,ua:`Які фактори можуть змінювати властивості гідроколоїдів?`},explanation:{en:`Material-specific hydration, concentration and chemistry are essential.`,ua:`Для результату важливі специфічні умови гідратації, концентрація та хімічне середовище.`},options:[{id:`a`,text:{en:`Concentration`,ua:`Концентрація`}},{id:`b`,text:{en:`The belief that all gelling agents are interchangeable`,ua:`Віра, що всі гелеутворювачі взаємозамінні`}},{id:`c`,text:{en:`Acidity and ions`,ua:`Кислотність та іони`}},{id:`d`,text:{en:`Hydration and temperature`,ua:`Гідратація та температура`}}],answer:{optionIds:[`a`,`c`,`d`]}},{id:`cooking-256-06`,theoryId:256,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A 500 g batch is designed for a 0.4% thickener concentration by total mass. How many grams of thickener are required?`,ua:`Для партії масою 500 г заплановано 0,4% загусника від загальної маси. Скільки грамів загусника потрібно?`},explanation:{en:`500 × 0.004 = 2 g. This is arithmetic practice, not a universal recommended dosage.`,ua:`500 × 0,004 = 2 г. Це вправа з розрахунку, а не універсальна рекомендована доза.`},numericInput:{unit:`g`,unitLabel:{en:`grams`,ua:`грамів`},allowDecimals:!1},answer:{value:2,tolerance:0,unit:`g`}},{id:`cooking-256-07`,theoryId:256,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which action is a formulation error when thickening fruit sauce with a hydrocolloid?`,ua:`Яка дія є помилкою рецептури під час загущення фруктового соусу гідроколоїдом?`},explanation:{en:`Hydrocolloids have different hydration and gelation mechanisms.`,ua:`Гідроколоїди мають різні механізми гідратації та гелеутворення.`},options:[{id:`a`,text:{en:`Substitute agar for xanthan at the same mass without testing`,ua:`Замінити агар на ксантан у тій самій масі без випробування`}},{id:`b`,text:{en:`Measure a small test batch`,ua:`Відміряти невелику пробну партію`}},{id:`c`,text:{en:`Record final texture and pH conditions`,ua:`Записати кінцеву текстуру та умови pH`}}],answer:{optionIds:[`a`]}}];var n={theoryId:256,exercises:i};export{n as default,i as exercises,a as theoryId};